(()=>{const canvas=document.querySelector('#abstract-form');if(!canvas||!window.ChaoMotionStudy)return;const study=new window.ChaoMotionStudy(canvas,5);study.centerY=.60;const layout=()=>{study.scale=innerWidth<700?.93:.68};layout();addEventListener('resize',layout);const reduced=matchMedia('(prefers-reduced-motion:reduce)');study.paused=reduced.matches;const pause=document.querySelector('#pause-motion');function pauseState(){pause.textContent=study.paused?'播放动画 ▷':'暂停动画 Ⅱ';pause.setAttribute('aria-pressed',String(study.paused))}pause.addEventListener('click',()=>{study.paused=!study.paused;study.energy=.01;pauseState()});pauseState();document.querySelector('#stir-pattern').addEventListener('click',()=>{study.energy=1});const toggle=document.querySelector('#toggle-form'),panel=document.querySelector('#form-settings');function close(){panel.hidden=true;toggle.setAttribute('aria-expanded','false')}toggle.addEventListener('click',()=>{panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden))});document.addEventListener('pointerdown',e=>{if(!e.target.closest('.object-toolbar'))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){close();toggle.focus()}});const loader=document.querySelector('.portal-loader');if(loader)loader.hidden=true;const cover=document.querySelector('.portfolio-cover');function headerState(){document.body.classList.toggle('cover-passed',!cover||scrollY>cover.offsetHeight-100)}addEventListener('scroll',headerState,{passive:true});headerState()})();
